options.styles:
& {
  --grid: #e0533c;
  --home: #3d8bfd;
  --muted: rgba(128, 128, 128, 0.35);
}

/* Drawn on a 440 x 400 grid like the Raggendorf flow; --u is one unit. */
& .dt-row {
  height: 100%;
  padding: 0;
  container-type: size;
}

& .stage {
  --u: calc(min(100cqw, 110cqh) / 440);
  position: relative;
  width: calc(var(--u) * 440);
  height: calc(var(--u) * 400);
  margin: 0 auto;
}

& .stage.stale {
  opacity: 0.4;
}

& .stage > div,
& .stage > a {
  position: absolute;
}

& a {
  color: inherit;
  text-decoration: none;
}

& a:focus-visible {
  outline: 2px solid var(--home);
  outline-offset: 2px;
}

& .site {
  left: 50%;
  top: 0;
  transform: translateX(-50%);
  font-size: calc(var(--u) * 15);
  font-weight: 700;
  letter-spacing: 0.15em;
}

& .updated {
  left: 50%;
  top: calc(var(--u) * 22);
  transform: translateX(-50%);
  font-size: calc(var(--u) * 12);
  opacity: 0.7;
}

& .tag {
  display: flex;
  flex-direction: column;
  align-items: center;
  line-height: 1.25;
  white-space: nowrap;
  transform: translateX(-50%);
  top: calc(var(--u) * 235);
}

& .name {
  font-size: calc(var(--u) * 12);
  opacity: 0.7;
}

& .value {
  font-size: calc(var(--u) * 16);
  font-weight: 600;
}

& .node {
  top: calc(var(--u) * 190);
  width: calc(var(--u) * 52);
  height: calc(var(--u) * 52);
  margin: calc(var(--u) * -26) 0 0 calc(var(--u) * -26);
  box-sizing: border-box;
  border: calc(var(--u) * 2.5) solid;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: calc(var(--u) * 22);
}

& .node.grid, & .tag.grid { left: calc(var(--u) * 110); }
& .node.apartment, & .tag.apartment { left: calc(var(--u) * 330); }
& .node.grid { border-color: var(--grid); }
& .node.apartment { border-color: var(--home); }

& .node.off {
  border-color: var(--muted);
  filter: grayscale(1);
  opacity: 0.6;
}

/* The line runs from the grid to the apartment; moving dots while the
   room is below its setpoint. */
& .line {
  left: calc(var(--u) * 136);
  top: calc(var(--u) * 190);
  width: calc(var(--u) * 168);
  height: calc(var(--u) * 3.5);
  margin-top: calc(var(--u) * -1.75);
  border-radius: 999px;
  --c: var(--grid);
  background: var(--muted);
}

& .line.on {
  background:
    radial-gradient(circle, var(--c) 40%, transparent 45%) 0 50% / calc(var(--u) * 10) 100% repeat-x,
    linear-gradient(color-mix(in srgb, var(--c) 35%, transparent), color-mix(in srgb, var(--c) 35%, transparent));
  animation: energy-flow 0.8s linear infinite;
}

@keyframes energy-flow {
  from { background-position: 0 50%, 0 0; }
  to { background-position: calc(var(--u) * 10) 50%, 0 0; }
}

@media (prefers-reduced-motion: reduce) {
  & .line.on { animation: none; }
}

@container (max-height: 200px) {
  & .stage {
    --u: calc(min(100cqw, 350cqh) / 440);
    height: calc(var(--u) * 126);
  }

  & .site {
    font-size: calc(var(--u) * 11);
    letter-spacing: 0.12em;
  }

  & .updated, & .tag.apartment .name:last-child {
    display: none;
  }

  & .node {
    top: calc(var(--u) * 46);
    width: calc(var(--u) * 44);
    height: calc(var(--u) * 44);
    margin: calc(var(--u) * -22) 0 0 calc(var(--u) * -22);
    font-size: calc(var(--u) * 20);
  }

  & .line {
    top: calc(var(--u) * 46);
    left: calc(var(--u) * 132);
    width: calc(var(--u) * 176);
  }

  & .tag {
    top: calc(var(--u) * 76);
  }

  & .tag .value { order: 1; }
  & .tag .name { order: 2; }
}
